"""Canonical finite v1.0 issue catalog used to configure GitHub.

Keep entries topologically ordered: dependencies must refer to earlier keys. The GitHub
bootstrapper validates this invariant and renders the complete issue template.
"""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True, slots=True)
class IssueSpec:
    key: str
    title: str
    milestone: str
    phase: str
    priority: str
    kind: str
    effort: str
    risk: str
    area: str
    dependencies: tuple[str, ...]
    scope: str
    acceptance: tuple[str, ...]
    tests: tuple[str, ...]


MILESTONES = (
    ("v0.1 — Foundation", "Repository, contracts, adapters, identities, discovery and graph."),
    ("v0.2 — Instrumentation", "Calibration and bounded, versioned feature extraction."),
    ("v0.3 — Mutation Lab", "Transactional masking, rollback and tiered cheap evaluation."),
    ("v0.4 — Experiment Dataset", "Resumable campaigns and leakage-safe persisted examples."),
    ("v0.5 — First Surgeon", "Heuristic and classical learned prediction baselines."),
    ("v0.6 — Active Surgeon", "Uncertainty-aware experiment selection and retraining."),
    ("v0.7 — Structural and Native GGUF Surgery", "Physical HF and out-of-core quantized GGUF surgery."),
    ("v0.8 — Cross-Model Generalization", "Held-out family, scale and quantization evaluation."),
    ("v0.9 — Automated Optimization", "Constrained iterative search and repair."),
    ("v1.0 — ModelSurgeon", "Stable, reproducible, documented end-to-end release."),
)

PHASES = (
    "Foundation", "Model Introspection", "Instrumentation", "Feature Extraction",
    "Mutation Engine", "Evaluation", "Experiment Dataset", "Baseline Surgeon",
    "Active Learning", "Search", "Structural Surgery", "Generalization",
    "Explainability", "Optimization", "Release",
)


def i(
    key: str,
    title: str,
    milestone: str,
    phase: str,
    priority: str,
    kind: str,
    effort: str,
    risk: str,
    area: str,
    dependencies: tuple[str, ...],
    scope: str,
    *acceptance: str,
    tests: tuple[str, ...] = (),
) -> IssueSpec:
    if not tests:
        tests = (f"Add focused automated tests for {title.lower()}.",)
    return IssueSpec(
        key, title, milestone, phase, priority, kind, effort, risk, area,
        dependencies, scope, tuple(acceptance), tests,
    )


