def validate_catalog() -> None:
    """Raise when keys, dependencies, fields, or topological order are invalid."""
    seen: set[str] = set()
    milestone_names = {name for name, _ in MILESTONES}
    for spec in ISSUES:
        if spec.key in seen:
            raise ValueError(f"duplicate issue key: {spec.key}")
        if spec.milestone not in milestone_names:
            raise ValueError(f"unknown milestone for {spec.key}: {spec.milestone}")
        if spec.phase not in PHASES:
            raise ValueError(f"unknown phase for {spec.key}: {spec.phase}")
        missing = set(spec.dependencies) - seen
        if missing:
            raise ValueError(f"{spec.key} depends on missing or later keys: {sorted(missing)}")
        if not spec.acceptance or not spec.tests:
            raise ValueError(f"{spec.key} lacks acceptance criteria or tests")
        seen.add(spec.key)


validate_catalog()
